#!/usr/bin/env node

/**
 * AI-Generated Test Runner
 * Executes tests generated by AI with enhanced capabilities
 */

import { AITestEnhancer } from './AITestEnhancer.ts';

async function runAIGeneratedTests() {
  console.log('=== Running AI-Generated Tests ===');
  
  try {
    // Initialize AI components
    await AITestEnhancer.initializeAIComponents();
    
    // Generate and run AI-enhanced test suite
    const result = await AITestEnhancer.generateAIEnhancedSuite(
      'src/components/MetricCard.astro',
      [], // No recent changes for demo
      undefined // No MCP session for demo
    );
    
    console.log(`Generated ${result.prioritization.tests.length} test scenarios`);
    console.log(`Estimated duration: ${result.prioritization.totalEstimatedTime} minutes`);
    console.log(`Confidence: ${result.prioritization.confidence}%`);
    
    // Execute individual AI-enhanced tests
    for (const testImpact of result.prioritization.tests.slice(0, 3)) { // Run first 3 for demo
      console.log(`\n--- Executing: ${testImpact.testId} ---`);
      
      const testResult = await AITestEnhancer.executeAIEnhancedTest(
        testImpact.testId,
        'src/components/MetricCard.astro'
      );
      
      if (testResult.success) {
        console.log(`   Status: PASSED`);
        console.log(`   Duration: ${testResult.result.executionTime} minutes`);
        console.log(`   AI-Generated: ${testResult.result.aiGenerated}`);
        console.log(`   MCP-Enhanced: ${testResult.result.mcpEnhanced}`);
        console.log(`   Self-Healing: ${testResult.result.selfHealing}`);
      } else {
        console.log(`   Status: FAILED`);
        console.log(`   Error: ${testResult.result.error}`);
        if (testResult.healing) {
          console.log(`   Healing Attempted: ${testResult.healing.reasoning}`);
        }
      }
    }
    
    // Display final statistics
    const stats = AITestEnhancer.getAIStatistics();
    console.log('\n=== AI Test Statistics ===');
    console.log(`MCP Tools Available: ${stats.mcp.availableTools}`);
    console.log(`ML Models: ${stats.ml.models.length}`);
    console.log(`Healing Statistics:`, stats.selfHealing.statistics);
    console.log(`Components Initialized: ${stats.overall.componentsInitialized}/3`);
    
    console.log('\n=== AI-Generated Tests Completed ===');
    
  } catch (error) {
    console.error('AI-generated test execution failed:', error);
    process.exit(1);
  } finally {
    // Cleanup
    await AITestEnhancer.cleanup();
  }
}

runAIGeneratedTests();
